void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec4 buffer0 = texelFetch(iChannel0, ivec2(fragCoord), 0);
    vec4 buffer1 = texelFetch(iChannel1, ivec2(fragCoord - vec2(iResolution.x / 2.0,0.0)), 0);

    fragColor = buffer0;

    if(fragCoord.x > iResolution.x /2.0) fragColor = vec4(hsv2rgb(vec3(mod(buffer1.x / 2.0 / pi, 1.0),1.0,1.0)),1.0);
}

const float pi = 3.141592;

uint hash(inout uint x ) {
    x += ( x << 10u );
    x ^= ( x >>  6u );
    x += ( x <<  3u );
    x ^= ( x >> 11u );
    x += ( x << 15u );
    return x;
}

float rand(inout uint seed)
{
    return fract(float(hash(seed))/ 4294967296.0);//4294967296 2 ^ 32 / 32 bit unsigned integer limit
}

float randNorm(inout uint seed)
{   
    float theta = 2.0 * pi * rand(seed);
    float rho = sqrt( -2.0 * log(rand(seed)));
    return rho * cos(theta);
}

vec2 randVec2Norm(inout uint seed)
{
    float x = randNorm(seed);
    float y = randNorm(seed);
    return vec2(x,y);
}

vec2 angle2vec2(in float theta)
{
    return vec2(cos(theta), sin(theta));
}

vec3 rgb2hsv(vec3 c)
{
    vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
    vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
    vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));

    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}

vec3 hsv2rgb(vec3 c)
{
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

const int KERNAL_SIZE = 1;

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = vec4(0.0);

    float modFrame = 20.0 + mod(float(iFrame) + iDate.w, 450.0);

    uint seed = uint((fragCoord.y * iResolution.x + fragCoord.x) * modFrame);

    if(iFrame == 2)
    {
        if (rand(seed) > 0.9) fragColor = vec4(randVec2Norm(seed),0.0,0.0);
        return;
    }

    vec4 buffer0 = texelFetch(iChannel0, ivec2(fragCoord), 0);

    vec4 color = buffer0;

    float minLength = 10000000.0;

    for(int y=-KERNAL_SIZE; y<=KERNAL_SIZE; y++)
    {
        for(int x=-KERNAL_SIZE; x<=KERNAL_SIZE; x++)
        {
            if(x == 0 && y == 0) continue;

            vec4 sample0 = texelFetch(iChannel0, ivec2(fragCoord) + ivec2(x,y), 0);

            if(sample0 == vec4(0.0)) continue;

            float sim = length(sample0.xy + vec2(x,y));

            if(sim <= minLength)
            {
                minLength = sim;
                color = sample0;
            }
        }
    }

    color = color + vec4(randVec2Norm(seed) / 10.0,vec2(0.0));

    fragColor = color;
}

const int KERNAL_SIZE = 2;

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float modFrame = 20.0 + mod(float(iFrame) + iDate.w, 450.0);

    uint seed = uint((fragCoord.y * iResolution.x + fragCoord.x) * modFrame);

    if(iFrame == 2)
    {
        fragColor = vec4(rand(seed) * 2.0 * pi,0.0,0.0,0.0);
        return;
    }

    vec4 buffer0 = texelFetch(iChannel0, ivec2(fragCoord), 0);

    vec4 color = buffer0;

    float minLength = 10000000.0;

    for(int y=-KERNAL_SIZE; y<=KERNAL_SIZE; y++)
    {
        for(int x=-KERNAL_SIZE; x<=KERNAL_SIZE; x++)
        {
            if(x == 0 && y == 0) continue;

            ivec2 samplePos = ivec2(fragCoord) + ivec2(x,y);

            if(mod(vec2(samplePos), iResolution.xy) != vec2(samplePos)) continue;

            vec4 sample0 = texelFetch(iChannel0, samplePos, 0);

            float sim = length(angle2vec2(sample0.x) + vec2(x,y));

            if(sim < minLength)
            {
                minLength = sim;
                color = sample0;
            }
        }
    }

    color = vec4(color.x + (rand(seed) * 2.0 - 1.0) / 8.0,0.0,0.0,0.0);

    fragColor = color;
}
